class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        result = []

        cnts = [0] * 26
        for c in p:
            cnts[ord(c) - ord('a')] += 1

        left, right = 0, 0
        while right < len(s):
            cnts[ord(s[right]) - ord('a')] -= 1
            while left <= right and cnts[ord(s[right]) - ord('a')] < 0:
                cnts[ord(s[left]) - ord('a')] += 1
                left += 1
            if right - left + 1 == len(p):
                result.append(left)
            right += 1

        return result

class Solution:
    def findKthNumber(self, n: int, k: int) -> int:

        def prefix(op,n):
            if op==n: return 1
            if int(op)>int(n): return 0
            for i in range(len(op)):
                if int(op[i])>int(n[i]): 
                    rem = len(n)-1-len(op)
                    if not rem: return 1
                    return 1+int(10*((1-10**rem)/-9))
                elif int(op[i])<int(n[i]): 
                    rem = len(n)-len(op)
                    if not rem: return 1
                    return 1+int(10*((1-10**rem)/-9))

            res = 1
            for i in range(10):
                res += prefix(op+str(i),n)
            return res

        ans = 1
        while k>1:
            pref = prefix(str(ans),str(n)) 
            if pref >= k:
                ans*=10; k-=1
            else: 
                ans += 1; k-= pref

        return ans

